class PowerDistributionNetwork:
    def __init__(self, busses, lines, lineimpedances, openlines):
        self.Busses = busses
        self.Lines = lines
        self.LineImpedances = lineimpedances
        self.OpenLines = openlines

    def availableLines(self):
        return [line for line in self.Lines if line not in self.OpenLines]

    def number_of_available_lines(self):
        return len(self.availableLines())

    def number_of_busses(self):
        return self.Busses

    def check_graph Connectivity(self, available_lines):
        import networkx as nx
        G = nx.Graph()
        G.add_nodes_from(range(1, self.number_of_busses()+1))
        G.add_edges_from(available_lines)
